def header_footer(canvas, doc, label='TirGeo Architecture'):
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor('#D7E3EC')); canvas.line(doc.leftMargin, 14*mm, doc.pagesize[0]-doc.rightMargin, 14*mm)
    canvas.setFont('Helvetica', 7.5); canvas.setFillColor(MUTED)
    canvas.drawString(doc.leftMargin, 9*mm, label)
    canvas.drawRightString(doc.pagesize[0]-doc.rightMargin, 9*mm, f'{doc.page}')
    canvas.restoreState()

def cover_page(canvas, doc, title, subtitle, audience):
    canvas.saveState(); w,h=doc.pagesize
    canvas.setFillColor(NAVY); canvas.rect(0,0,w,h,fill=1,stroke=0)
    canvas.setFillColor(BLUE); canvas.rect(0,0,18*mm,h,fill=1,stroke=0)
    canvas.setFillColor(CYAN); canvas.circle(w-25*mm,h-28*mm,16*mm,fill=1,stroke=0)
    canvas.setFillColor(TEAL); canvas.circle(w-47*mm,h-18*mm,7*mm,fill=1,stroke=0)
    canvas.setFillColor(WHITE); canvas.setFont('Helvetica-Bold',12); canvas.drawString(30*mm,h-35*mm,'TIRGEO')
    canvas.setFont('Helvetica-Bold',30); canvas.drawString(30*mm,h-78*mm,title)
    canvas.setFont('Helvetica',13); canvas.setFillColor(colors.HexColor('#D9EAF4'))
    ty=h-96*mm
    for line in subtitle.split('\n'): canvas.drawString(30*mm,ty,line); ty-=7*mm
    canvas.setFont('Helvetica-Bold',9); canvas.setFillColor(CYAN); canvas.drawString(30*mm,38*mm,audience.upper())
    canvas.setFont('Helvetica',8); canvas.setFillColor(colors.HexColor('#B8D2E3')); canvas.drawString(30*mm,29*mm,'Architecture snapshot - 3 July 2026')
    canvas.restoreState()

def box(d,x,y,w,h,title,subtitle='',fill=PALE,stroke=BLUE,title_size=9):
    d.add(Rect(x,y,w,h,rx=6,ry=6,fillColor=fill,strokeColor=stroke,strokeWidth=1.2))
    d.add(String(x+w/2,y+h-14,title,fontName='Helvetica-Bold',fontSize=title_size,fillColor=NAVY,textAnchor='middle'))
    if subtitle:
        lines=subtitle.split('\n')
        for i,line in enumerate(lines[:4]): d.add(String(x+w/2,y+h-29-i*10,line,fontName='Helvetica',fontSize=6.6,fillColor=INK,textAnchor='middle'))

def arrow(d,x1,y1,x2,y2,color=MUTED):
    d.add(Line(x1,y1,x2,y2,strokeColor=color,strokeWidth=1.3))
    import math
    a=math.atan2(y2-y1,x2-x1); s=5
    pts=[x2,y2,x2-s*math.cos(a-.55),y2-s*math.sin(a-.55),x2-s*math.cos(a+.55),y2-s*math.sin(a+.55)]
    d.add(Polygon(pts,fillColor=color,strokeColor=color))

def architecture_diagram(width=500,height=245):
    d=Drawing(width,height)
    box(d,10,150,105,58,'Mobile / Web UI','Employee\nSupervisor\nAdmin',GREENPALE,TEAL)
    box(d,145,145,120,68,'Fastify API','JWT + RBAC\nZod validation\nRate limiting',PALE,BLUE)
    box(d,300,155,95,50,'Prisma ORM','Typed queries\nTransactions',PALE2,MUTED)
    box(d,420,155,70,50,'PostgreSQL','Operational\ndata',GREENPALE,TEAL)
    box(d,145,45,100,52,'Offline Sync','Audit cursor\nMutation receipts',PALE,BLUE)
    box(d,275,45,100,52,'File Storage','Tender files\nAttachments',PALE2,MUTED)
    box(d,400,45,90,52,'External','Xero / MYOB\nPush / email',colors.HexColor('#FFF2E8'),ORANGE)
    arrow(d,115,179,145,179); arrow(d,265,179,300,179); arrow(d,395,179,420,179)
    arrow(d,205,145,195,97); arrow(d,245,71,275,71); arrow(d,375,71,400,71)
    d.add(String(250,225,'Current backend wiring and integration boundaries',fontName='Helvetica-Bold',fontSize=11,fillColor=NAVY,textAnchor='middle'))
    return d

def flow_diagram(steps, width=500, height=95, colorset=None):
    d=Drawing(width,height); n=len(steps); gap=10; bw=(width-gap*(n-1))/n
    for i,(title,sub) in enumerate(steps):
        x=i*(bw+gap); fill=(colorset[i] if colorset else (GREENPALE if i==n-1 else PALE))
        box(d,x,20,bw,55,title,sub,fill,TEAL if i==n-1 else BLUE,7.5)
        if i<n-1: arrow(d,x+bw,47,x+bw+gap,47)
    return d

def callout(text, color=PALE):
    t=Table([[Paragraph(text,styles['Callout'])]],colWidths=[170*mm])
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),color),('BOX',(0,0),(-1,-1),0.7,BLUE),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)])); return t

def table(data,widths,small=False,header=True):
    cooked=[]
    for r,row in enumerate(data):
        cooked.append([Paragraph(str(v), styles['Smallx'] if small or r else styles['Bodyx']) for v in row])
    t=Table(cooked,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    cmds=[('GRID',(0,0),(-1,-1),.35,colors.HexColor('#C9D7E3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]
    if header: cmds += [('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),WHITE),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold')]
    for r in range(1 if header else 0,len(data)):
        if r%2==0: cmds.append(('BACKGROUND',(0,r),(-1,r),PALE2))
    t.setStyle(TableStyle(cmds)); return t

